"use strict";const fs=require("fs");const path=require("path");const{execSync}=require("child_process");const PROJECT_ROOT=path.resolve(__dirname,"../..");const SHARED_MODULE_PATTERN=/(KiiPS-COMMON|KiiPS-UTILS)\//;const STATE_FILE=path.join(PROJECT_ROOT,".claude/state/.impact-analysis.json");const NOTIFY_INTERVAL_MS=30*60*1e3;const REFERENCE_THRESHOLD=5;function loadState(){try{return JSON.parse(fs.readFileSync(STATE_FILE,"utf8"))}catch(_){return{notified:{}}}}function saveState(state){try{const dir=path.dirname(STATE_FILE);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(STATE_FILE,JSON.stringify(state,null,2),"utf8")}catch(_){}}function extractClassName(filePath){if(!filePath.endsWith(".java"))return null;const baseName=path.basename(filePath,".java");if(!/^[A-Z][A-Za-z0-9_]*$/.test(baseName))return null;return baseName}function findReferencingModules(className){const referenced=new Set;try{let cmd="";try{execSync("which rg",{stdio:"ignore"});cmd=`rg -l --no-ignore -g '!.claude' -g '*.java' '\\b${className}\\b' "${PROJECT_ROOT}"`}catch(_){cmd=`grep -rl --include='*.java' --exclude-dir=.claude '\\b${className}\\b' "${PROJECT_ROOT}"`}const output=execSync(cmd,{timeout:8e3,encoding:"utf8",stdio:["ignore","pipe","ignore"]});output.split("\n").filter(Boolean).forEach(p=>{const m=p.match(/(KiiPS-[A-Z]+|KIIPS-[A-Z]+)/);if(m)referenced.add(m[1])})}catch(_){}return Array.from(referenced)}function analyzeImpact(filePath){if(!SHARED_MODULE_PATTERN.test(filePath))return;if(!filePath.endsWith(".java"))return;const className=extractClassName(filePath);if(!className)return;const state=loadState();const lastNotified=(state.notified||{})[filePath]||0;if(Date.now()-lastNotified<NOTIFY_INTERVAL_MS)return;const modules=findReferencingModules(className);const ownModule=filePath.match(/(KiiPS-[A-Z]+|KIIPS-[A-Z]+)/);const externalModules=modules.filter(m=>!ownModule||m!==ownModule[1]);if(externalModules.length<REFERENCE_THRESHOLD){state.notified=state.notified||{};state.notified[filePath]=Date.now();saveState(state);return}const lines=[];lines.push("");lines.push("┌─── IMPACT ANALYSIS — SHARED MODULE GATE ─────────┐");lines.push(`│ Class: ${className}`.padEnd(51)+"│");lines.push(`│ Modified file: ${path.basename(filePath)}`.padEnd(51)+"│");lines.push(`│ Referenced by ${externalModules.length} modules`.padEnd(51)+"│");lines.push("│                                                  │");lines.push("│ Affected modules:                                │");externalModules.slice(0,8).forEach(m=>{lines.push(`│   - ${m}`.padEnd(51)+"│")});if(externalModules.length>8){lines.push(`│   ... and ${externalModules.length-8} more`.padEnd(51)+"│")}lines.push("│                                                  │");lines.push("│ Per Golden Principle #1 (Immutability):          │");lines.push("│   - 시그니처 변경 금지, 새 메서드 추가로 확장      │");lines.push("│   - 사용자 명시 승인 필요                         │");lines.push("│                                                  │");lines.push("│ Reference: KiiPS-COMMON/CLAUDE.md                │");lines.push("└──────────────────────────────────────────────────┘");lines.push("");process.stderr.write(lines.join("\n"));state.notified=state.notified||{};state.notified[filePath]=Date.now();saveState(state)}if(require.main===module){const chunks=[];process.stdin.setEncoding("utf8");process.stdin.on("data",c=>chunks.push(c));process.stdin.on("end",()=>{try{const input=chunks.join("");if(!input.trim())process.exit(0);const event=JSON.parse(input);const toolName=event.tool_name||"";const toolInput=event.tool_input||{};if(!["Edit","Write"].includes(toolName))process.exit(0);const filePath=toolInput.file_path;if(!filePath)process.exit(0);analyzeImpact(filePath)}catch(_){}process.exit(0)});process.stdin.resume()}module.exports={analyzeImpact:analyzeImpact,extractClassName:extractClassName,findReferencingModules:findReferencingModules,REFERENCE_THRESHOLD:REFERENCE_THRESHOLD};